const std = @import("std");

pub const Role = enum { user, assistant };

pub const Message = struct {
    role: Role,
    content: []u8,
};

pub const MessageCopy = Message;

pub const SessionMeta = struct {
    session_id: []u8,
    preview: []u8,
    count: usize,
    updated_at: i64,
};

pub const Session = struct {
    id: []u8,
    messages: std.ArrayList(Message),
    created_at: i64,
    updated_at: i64,
};

pub const Store = struct {
    allocator: std.mem.Allocator,
    mutex: std.Thread.Mutex,
    sessions: std.StringHashMap(*Session),

    pub fn init(allocator: std.mem.Allocator) Store {
        return .{
            .allocator = allocator,
            .mutex = .{},
            .sessions = std.StringHashMap(*Session).init(allocator),
        };
    }

    pub fn deinit(self: *Store) void {
        self.mutex.lock();
        defer self.mutex.unlock();

        var it = self.sessions.valueIterator();
        while (it.next()) |sess_ptr| {
            freeSession(self.allocator, sess_ptr.*);
        }
        self.sessions.deinit();
    }

    pub fn getOrCreate(self: *Store, requested: ?[]const u8) ![]u8 {
        self.mutex.lock();
        defer self.mutex.unlock();

        if (requested) |req| {
            if (isValidId(req)) {
                if (self.sessions.get(req)) |sess| {
                    return self.allocator.dupe(u8, sess.id);
                }

                const id_copy = try self.allocator.dupe(u8, req);
                errdefer self.allocator.free(id_copy);

                const sess = try self.allocator.create(Session);
                errdefer self.allocator.destroy(sess);

                const now = std.time.timestamp();
                sess.* = .{
                    .id = id_copy,
                    .messages = .empty,
                    .created_at = now,
                    .updated_at = now,
                };

                const result = try self.allocator.dupe(u8, id_copy);
                errdefer self.allocator.free(result);

                try self.sessions.putNoClobber(id_copy, sess);
                return result;
            }
        }

        while (true) {
            const new_id = try generateId(self.allocator);
            errdefer self.allocator.free(new_id);

            if (self.sessions.contains(new_id)) {
                self.allocator.free(new_id);
                continue;
            }

            const sess = try self.allocator.create(Session);
            errdefer self.allocator.destroy(sess);

            const now = std.time.timestamp();
            sess.* = .{
                .id = new_id,
                .messages = .empty,
                .created_at = now,
                .updated_at = now,
            };

            const result = try self.allocator.dupe(u8, new_id);
            errdefer self.allocator.free(result);

            try self.sessions.putNoClobber(new_id, sess);
            return result;
        }
    }

    pub fn append(self: *Store, id: []const u8, role: Role, content: []const u8) !bool {
        self.mutex.lock();
        defer self.mutex.unlock();

        const sess = self.sessions.get(id) orelse return false;
        const dup = try self.allocator.dupe(u8, content);
        errdefer self.allocator.free(dup);
        try sess.messages.append(self.allocator, .{ .role = role, .content = dup });
        sess.updated_at = std.time.timestamp();
        return true;
    }

    pub fn snapshot(self: *Store, allocator: std.mem.Allocator, id: []const u8) ![]MessageCopy {
        self.mutex.lock();
        defer self.mutex.unlock();

        const sess = self.sessions.get(id) orelse return error.SessionNotFound;

        const out = try allocator.alloc(MessageCopy, sess.messages.items.len);
        var n: usize = 0;
        errdefer {
            var i: usize = 0;
            while (i < n) : (i += 1) allocator.free(out[i].content);
            allocator.free(out);
        }

        for (sess.messages.items, 0..) |m, i| {
            const dup = try allocator.dupe(u8, m.content);
            out[i] = .{ .role = m.role, .content = dup };
            n += 1;
        }

        return out;
    }

    pub fn freeMessageCopies(allocator: std.mem.Allocator, msgs: []MessageCopy) void {
        for (msgs) |m| allocator.free(m.content);
        allocator.free(msgs);
    }

    pub fn list(self: *Store, allocator: std.mem.Allocator) ![]SessionMeta {
        self.mutex.lock();
        defer self.mutex.unlock();

        const out = try allocator.alloc(SessionMeta, self.sessions.count());
        var n: usize = 0;
        errdefer {
            var i: usize = 0;
            while (i < n) : (i += 1) {
                allocator.free(out[i].session_id);
                allocator.free(out[i].preview);
            }
            allocator.free(out);
        }

        var it = self.sessions.valueIterator();
        while (it.next()) |sess_ptr| {
            const sess = sess_ptr.*;

            const preview_source = if (sess.messages.items.len > 0)
                sess.messages.items[0].content
            else
                "";

            const preview_slice = safeUtf8Slice(preview_source, 80);
            const preview = try allocator.dupe(u8, preview_slice);
            errdefer allocator.free(preview);

            const id_copy = try allocator.dupe(u8, sess.id);
            errdefer allocator.free(id_copy);

            out[n] = .{
                .session_id = id_copy,
                .preview = preview,
                .count = sess.messages.items.len,
                .updated_at = sess.updated_at,
            };
            n += 1;
        }

        std.mem.sort(SessionMeta, out, {}, sessionMetaDescByTime);
        return out;
    }

    pub fn freeList(allocator: std.mem.Allocator, list_items: []SessionMeta) void {
        for (list_items) |m| {
            allocator.free(m.session_id);
            allocator.free(m.preview);
        }
        allocator.free(list_items);
    }

    pub fn delete(self: *Store, id: []const u8) bool {
        self.mutex.lock();
        defer self.mutex.unlock();

        const entry = self.sessions.fetchRemove(id) orelse return false;
        freeSession(self.allocator, entry.value);
        return true;
    }
};

fn freeSession(allocator: std.mem.Allocator, sess: *Session) void {
    for (sess.messages.items) |m| allocator.free(m.content);
    sess.messages.deinit(allocator);
    allocator.free(sess.id);
    allocator.destroy(sess);
}

fn sessionMetaDescByTime(_: void, a: SessionMeta, b: SessionMeta) bool {
    return a.updated_at > b.updated_at;
}

pub fn isValidId(id: []const u8) bool {
    if (id.len != 32) return false;
    for (id) |c| {
        const ok = (c >= '0' and c <= '9') or (c >= 'a' and c <= 'f');
        if (!ok) return false;
    }
    return true;
}

fn generateId(allocator: std.mem.Allocator) ![]u8 {
    var bytes: [16]u8 = undefined;
    std.crypto.random.bytes(&bytes);
    const hex = "0123456789abcdef";
    const out = try allocator.alloc(u8, 32);
    for (bytes, 0..) |b, i| {
        out[i * 2] = hex[b >> 4];
        out[i * 2 + 1] = hex[b & 0x0F];
    }
    return out;
}

fn safeUtf8Slice(s: []const u8, max_bytes: usize) []const u8 {
    if (s.len <= max_bytes) return s;
    var end = max_bytes;
    while (end > 0 and (s[end] & 0xC0) == 0x80) end -= 1;
    return s[0..end];
}

